insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('af388eaa-9708-5e69-af52-371229c85588', 'full-mock-2', 'Full Mock 2', 'Harder practice test — upper adaptive path', 'full_mock', 'both', null, 'hard', 'Four timed parts: two Reading and Writing modules of 27 questions and two Math modules of 22 questions. Pitched harder than Mock 1, matching the difficulty of the second module you would be routed into after a strong first module.', 2) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('420baa26-c84c-56c4-a2d3-e0f121eaa890', 'af388eaa-9708-5e69-af52-371229c85588', 1, 'Reading and Writing — Module 1', 'rw', 1920) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cf7c04d6-74c7-5e40-a78d-f8264fc46594', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'For decades the fossil was described as a juvenile of a well-known species. A 2019 reanalysis of its bone microstructure showed it was fully grown, which _______ the original classification and forced a new species name.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"undermined"},{"key":"B","text":"confirmed"},{"key":"C","text":"postponed"},{"key":"D","text":"summarised"}]'::jsonb, 'A', null, 'The reanalysis contradicted the old classification and forced a change, so it weakened it. ''Confirmed'' reverses the relationship, which the words ''forced a new species name'' rule out.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8d1a95c2-62f3-5f0b-a4bb-0735d9862624', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 2, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Historians long relied on a single memoir for their account of the siege. Recently uncovered letters from three merchants describe the same shortages and the same failed negotiation, which serves to _______ the memoir''s account rather than replace it.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"complicate"},{"key":"B","text":"corroborate"},{"key":"C","text":"abbreviate"},{"key":"D","text":"supersede"}]'::jsonb, 'B', null, 'Independent sources describing the same events provide supporting evidence, which is what ''corroborate'' means. ''Supersede'' is ruled out directly by ''rather than replace it''.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0f33e3f3-683b-546f-a31f-69ff9c533427', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 3, 'craft_structure', 'words_in_context', 'medium', 'mc', 'The connection the author draws between the two rebellions rests on a single ambiguous phrase in one letter. Without further documentation, the link remains _______, however appealing the parallel may be.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"conventional"},{"key":"B","text":"deliberate"},{"key":"C","text":"tenuous"},{"key":"D","text":"widespread"}]'::jsonb, 'C', null, 'A link resting on one ambiguous phrase and lacking documentation is weak, which is precisely what ''tenuous'' means. ''Conventional'' would describe how ordinary the claim is, not how well supported it is.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1548793a-77c2-570c-ac8d-6ecaa616a8c2', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 4, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'Rooftop gardens are often promoted as a way to cool cities. They do lower the temperature of the roof beneath them, sometimes markedly. But a roof is a small fraction of a building''s exposed surface, and measurements at street level rarely show any change at all. The benefit is real; it is simply located somewhere other than where it is usually claimed to be.', 'What is the main purpose of the text?', '[{"key":"A","text":"To argue that rooftop gardens should not be built in cities"},{"key":"B","text":"To compare rooftop gardens with other methods of cooling buildings"},{"key":"C","text":"To explain the engineering required to install a rooftop garden"},{"key":"D","text":"To correct where the cooling benefit of rooftop gardens actually occurs"}]'::jsonb, 'D', null, 'The text grants that the cooling is real and then relocates it from the street to the roof itself, which the final sentence states outright. Choice A overstates the point: the passage never recommends against building them.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('22bef5c6-3192-5cc8-ac61-8de0a7f0c90a', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 5, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Critics praised the novel''s dialogue for its _______: characters interrupt each other, trail off, and repeat themselves in ways that reproduce the texture of unscripted speech without ever becoming tedious to read.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"verisimilitude"},{"key":"B","text":"brevity"},{"key":"C","text":"formality"},{"key":"D","text":"ambivalence"}]'::jsonb, 'A', null, 'The colon explains the praise as dialogue that reproduces how real speech sounds, and ''verisimilitude'' means the appearance of being true to life. ''Brevity'' is tempting because of ''trail off'', but the passage describes repetition, not shortness.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8d4baaaa-6187-5114-a1c8-fcb37d7d37d5', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 6, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'The following is adapted from a short story. Every evening Tesfaye counted the till twice, though the shop took so little that a single count would have done. The second count was not for the money. It was for the ten minutes it bought him at the counter, after the door was locked and before the walk home.', 'What is the main function of the final sentence in the text as a whole?', '[{"key":"A","text":"It suggests that the character suspects someone of stealing from the shop."},{"key":"B","text":"It reveals that the character''s ritual serves a purpose unrelated to its stated one."},{"key":"C","text":"It establishes that the shop is more profitable than it first appears."},{"key":"D","text":"It explains why the character prefers to work alone in the evenings."}]'::jsonb, 'B', null, 'The passage sets up a redundant task and then explains that its real value is the time it buys him alone, not the accuracy of the count. Choice A contradicts ''The second count was not for the money''.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d2168406-14da-5f14-a36b-7f4af7c4a2d2', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 7, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: A widely cited study argues that open-plan offices increase collaboration, because removing physical barriers makes informal conversation easier.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cc618303-a066-5038-aa39-e02926571436', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 8, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: A curator argues that returning artefacts to their countries of origin risks dispersing collections that allow scholars to compare objects from many cultures side by side.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('bb51e45d-b81b-5932-af17-e02b442583c3', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 9, 'information_ideas', 'central_ideas_details', 'easy', 'mc', 'Cuttlefish change colour using pigment sacs controlled directly by muscle. Because no chemical signalling stands between the animal and the change, a cuttlefish can shift its entire appearance in under a second — faster than a chameleon, whose colour change depends on slower hormonal cues.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"The speed of a cuttlefish''s colour change follows from the direct muscular control behind it."},{"key":"B","text":"Cuttlefish and chameleons use the same mechanism to change colour."},{"key":"C","text":"Chameleons change colour for reasons that scientists do not yet understand."},{"key":"D","text":"Colour change is more common among marine animals than land animals."}]'::jsonb, 'A', null, 'The passage links the mechanism (muscle acting directly, with no chemical step) to the outcome (speed), and uses the chameleon only as a contrast. Choice B contradicts that contrast.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a46b5a5c-6c9c-5b5a-adf8-89019dda4c86', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 10, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'When a language loses its last fluent speakers, what disappears is not only vocabulary. Many endangered languages encode ecological knowledge in their grammar — obligatory markers for whether a plant is edible, or whether a report is first-hand. Translating the words is straightforward; translating what the grammar required a speaker to know is not.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Endangered languages are more grammatically complex than widely spoken ones."},{"key":"B","text":"Language loss removes knowledge that is built into grammar and resists translation."},{"key":"C","text":"Dictionaries are sufficient to preserve a language once its speakers are gone."},{"key":"D","text":"Most endangered languages are spoken by communities that rely on local plants."}]'::jsonb, 'B', null, 'The text distinguishes vocabulary, which translates easily, from grammatically encoded knowledge, which does not — and identifies the latter as the real loss. Choice C is contradicted by the final sentence.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b30d1d21-1bdf-5baa-af43-2233630598b7', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 11, 'information_ideas', 'evidence_textual', 'medium', 'mc', 'A historian claims that the city''s nineteenth-century sanitation reforms were driven less by medical evidence than by commercial pressure, since the diseases in question had already been described for decades without prompting action.', 'Which finding, if true, would most directly support the historian''s claim?', '[{"key":"A","text":"Physicians in the city published detailed reports on waterborne disease in the 1840s."},{"key":"B","text":"The city''s population grew rapidly throughout the nineteenth century."},{"key":"C","text":"The reforms began within a year of merchants reporting that quarantines were disrupting shipping."},{"key":"D","text":"Similar reforms were adopted in several other cities during the same period."}]'::jsonb, 'C', null, 'The claim is about what triggered action, so evidence tying the timing of reform to commercial pressure is what supports it. Choice A supports only the second half of the claim — that medical knowledge existed earlier — without showing what finally caused the change.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5b4d1025-06e9-506d-a792-dd82ae157267', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 12, 'information_ideas', 'inferences', 'medium', 'mc', 'Early radio dramas were performed live, with no means of recording them. Networks kept scripts, sound-effect notes, and contracts, but the broadcasts themselves survive only where a listener happened to point a home disc-cutter at the loudspeaker. Historians of the period therefore _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"have concluded that early radio dramas were rarely popular with listeners."},{"key":"B","text":"consider the surviving home recordings to be of higher quality than studio copies."},{"key":"C","text":"have been able to reconstruct complete broadcasts from network archives."},{"key":"D","text":"know more about how these dramas were planned than about how they sounded."}]'::jsonb, 'D', null, 'Scripts and production papers survive while the sound almost never does, so the surviving record is far stronger on planning than on performance. Choice C contradicts the statement that broadcasts survive only by accident.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d6c95832-47b1-53af-afb7-8898dc647084', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 13, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'In her study of urban foxes, a biologist proposes that boldness around humans is learned within a generation rather than inherited, noting that fox populations in newly urbanised areas become tolerant of people far faster than selection on an inherited trait could plausibly act.', 'Which finding, if true, would most directly weaken the biologist''s proposal?', '[{"key":"A","text":"Cubs born to bold urban parents but raised by wary rural foster parents remain bold as adults."},{"key":"B","text":"Urban foxes approach humans more closely than rural foxes do."},{"key":"C","text":"Foxes in newly urbanised areas take about two years to become tolerant of people."},{"key":"D","text":"Rural foxes will approach humans when food is scarce."}]'::jsonb, 'A', null, 'If boldness persists despite being raised by wary parents, it is travelling with heredity rather than being learned from the environment, which is exactly what the proposal denies. Choice B is consistent with either explanation and so distinguishes nothing.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6d75a5de-b778-51e2-a4f3-52cc9eed94b8', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 14, 'information_ideas', 'evidence_quantitative', 'hard', 'mc', 'A team measured germination rates for four seed batches stored for five years at different humidity levels. Batch W, stored at 15% humidity, germinated at 88%. Batch X, at 30%, germinated at 71%. Batch Y, at 45%, germinated at 44%. Batch Z, at 60%, germinated at 41%.', 'Which statement is best supported by the data?', '[{"key":"A","text":"Germination was unaffected by storage humidity across the range tested."},{"key":"B","text":"Germination declined steadily as storage humidity rose, with the sharpest drop between 30% and 45%."},{"key":"C","text":"The batch stored at the highest humidity germinated at more than half the rate of the driest batch."},{"key":"D","text":"Germination fell by an equal amount with each increase in storage humidity."}]'::jsonb, 'B', null, 'The rates fall throughout (88, 71, 44, 41) and the largest single drop is 71 to 44, a fall of 27 points. Choice D is wrong because the drops are 17, 27 and 3 — clearly unequal — and choice C fails since 41 is less than half of 88.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0d75e337-0c97-5bba-af1f-cec9dc29e5ba', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 15, 'information_ideas', 'inferences', 'hard', 'mc', 'A common assumption holds that species with larger brains relative to body size are better at solving novel problems. Yet among birds, the strongest predictor of success on unfamiliar foraging tasks is not relative brain size but whether the species is a generalist feeder. Several small-brained generalists outperform large-brained specialists. This suggests that _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"relative brain size is unrelated to any measure of avian behaviour."},{"key":"B","text":"specialist feeders are unable to learn new foraging techniques."},{"key":"C","text":"what a species habitually does may shape problem-solving more than how large its brain is."},{"key":"D","text":"researchers should stop measuring brain size in comparative studies."}]'::jsonb, 'C', null, 'The evidence contrasts a structural trait with an ecological habit and finds the habit more predictive, so the inference concerns what the animal does. Choices A and D overreach: the passage limits itself to one class of task, not to all uses of brain size.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5b106f6d-0442-5084-ab60-6b64231569e5', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 16, 'standard_conventions', 'boundaries', 'easy', 'mc', 'The archive holds more than four thousand photographic plates _______ most of them have never been printed.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":" "},{"key":"C","text":" and, "},{"key":"D","text":"; "}]'::jsonb, 'D', null, 'Both halves are complete sentences, so they need a semicolon or a comma plus a conjunction. A comma alone, as in choice A, creates a comma splice.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f87436cf-09dc-5baa-a006-2e18b93dffb9', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 17, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Because the reservoir supplies three districts _______ engineers monitor its level daily throughout the dry season.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":"; "},{"key":"C","text":": "},{"key":"D","text":" "}]'::jsonb, 'A', null, 'The opening clause begins with ''Because'', making it dependent, so it is joined to the main clause with a comma. A semicolon or colon would require a complete sentence on both sides.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('06bfe94e-089e-5b74-a19d-6ef8b1f2830b', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 18, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The 1908 expedition returned with one significant find _______ a fragment of woven cloth preserved in peat.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"; "},{"key":"B","text":": "},{"key":"C","text":", and "},{"key":"D","text":" which was "}]'::jsonb, 'B', null, 'The second part names and explains the ''one significant find'', which is exactly the job of a colon after a complete sentence. A semicolon in choice A would require an independent clause after it, and the fragment is not one.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('476e9b15-884b-5647-af6d-b925686d3249', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 19, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'A collection of letters, diaries, and municipal receipts _______ the only surviving record of the town''s founding decade.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"constitute"},{"key":"B","text":"have constituted"},{"key":"C","text":"constitutes"},{"key":"D","text":"were constituting"}]'::jsonb, 'C', null, 'The subject is ''A collection'', which is singular; ''of letters, diaries, and municipal receipts'' is a prepositional phrase and cannot govern the verb. The plural nouns just before the blank are what make the plural choices tempting.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5e70fb9c-fa3b-5ff7-a9b0-a75a53a80315', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 20, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The composer''s final quartet _______ was not performed publicly until 1971.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":" written in the year before her death,"},{"key":"B","text":", written in the year before her death"},{"key":"C","text":" written in the year before her death"},{"key":"D","text":", written in the year before her death,"}]'::jsonb, 'D', null, '''Written in the year before her death'' is extra, non-essential information, so it needs punctuation on both sides. Using only one comma, as in choices A and B, separates the subject from its verb and leaves the interrupter half-enclosed.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6273d42e-6daf-571a-ab8c-adcb9b536c08', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 21, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'Having been buried under volcanic ash for seventeen centuries _______ when excavation finally began in 1954.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"the frescoes retained much of their original colour"},{"key":"B","text":"excavators found the frescoes had retained much of their original colour"},{"key":"C","text":"it was found that the frescoes retained much of their original colour"},{"key":"D","text":"much of the frescoes'' original colour had been retained"}]'::jsonb, 'A', null, 'The opening modifier describes whatever was buried for seventeen centuries, so the frescoes must be the subject that follows it. Choice B makes the excavators the buried party, and choices C and D bury ''it'' and ''colour'' respectively.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('11769c0e-3b70-54be-aa0e-ae99b99a6216', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 22, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'By the time the survey team reached the summit ridge, the storm _______ for six hours, and the last of the marker flags had been torn away.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"has been blowing"},{"key":"B","text":"had been blowing"},{"key":"C","text":"is blowing"},{"key":"D","text":"will have been blowing"}]'::jsonb, 'B', null, 'The storm began before the team arrived, and both events are in the past, so the earlier one takes the past perfect. Choice A shifts to the present perfect, which would tie the storm to now rather than to the moment of arrival.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('46444bf8-b927-535f-a98f-f8c21df40c0e', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 23, 'expression_ideas', 'transitions', 'medium', 'mc', 'Solar panels generate the most electricity in the middle of the day, while household demand peaks in the early evening. _______ grid operators increasingly pair new solar installations with battery storage.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"For this reason,"},{"key":"D","text":"In contrast,"}]'::jsonb, 'C', null, 'The mismatch between generation and demand is the reason batteries are added, so the relationship is cause to effect. ''Nevertheless'' would signal a concession, but nothing in the second sentence contradicts the first.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('48b7e1dd-161c-5eda-a9d9-bb28ba1d86e1', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 24, 'expression_ideas', 'rhetorical_synthesis', 'medium', 'mc', 'While researching, a student has taken these notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b0b14df6-e9e9-5ea9-ac80-459ef4fde6d7', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 25, 'expression_ideas', 'transitions', 'hard', 'mc', 'Most models predicted that the reintroduced beavers would take a decade to alter the valley''s hydrology. _______ measurable changes in the water table appeared within three years.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"In fact,"},{"key":"B","text":"Therefore,"},{"key":"C","text":"Likewise,"},{"key":"D","text":"For example,"}]'::jsonb, 'A', null, 'The result contradicts the prediction, and ''In fact'' introduces a correction of that kind. ''Therefore'' would make the fast change follow from the slow prediction, which reverses the logic.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8bdbc977-39e3-5e0f-a2c1-2ca3b5ae9322', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 26, 'expression_ideas', 'transitions', 'hard', 'mc', 'The manuscript''s marginal notes are written in at least three hands, and the ink of the latest differs chemically from the others. _______ the annotations cannot all be attributed to the original owner, as earlier catalogues assumed.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"However,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"Admittedly,"}]'::jsonb, 'B', null, 'The physical evidence about hands and ink leads directly to the conclusion about authorship, so the link is consequence. ''However'' would set the conclusion against the evidence, but here it follows from it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2e5faed2-5b6d-5bff-a577-d5498d4780b0', '420baa26-c84c-56c4-a2d3-e0f121eaa890', 27, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching, a student has taken these notes:
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('9a97ea22-391b-5b39-a318-f200a343454c', 'af388eaa-9708-5e69-af52-371229c85588', 2, 'Reading and Writing — Module 2', 'rw', 1920) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c5287f62-3cda-56f5-aaa1-2a652573ccc7', '9a97ea22-391b-5b39-a318-f200a343454c', 1, 'craft_structure', 'words_in_context', 'medium', 'mc', 'The council''s endorsement was carefully worded to commit it to nothing. Members praised the proposal''s ambition, noted the need for further study, and set no date — a _______ that satisfied both factions precisely because it obliged neither.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"compromise"},{"key":"B","text":"denunciation"},{"key":"C","text":"mandate"},{"key":"D","text":"precedent"}]'::jsonb, 'A', null, 'A statement designed to satisfy two opposed factions by obliging neither is a middle position, which is what ''compromise'' names. ''Mandate'' would require the council to have ordered something, which the passage says it avoided.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8dabca5b-a979-5627-a7ba-5b65b6219712', '9a97ea22-391b-5b39-a318-f200a343454c', 2, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Once considered _______ by engineers who preferred digital control, the mechanical governor has returned to some turbine designs: it fails gradually and predictably, whereas a failed controller can stop a machine without warning.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"hazardous"},{"key":"B","text":"obsolete"},{"key":"C","text":"expensive"},{"key":"D","text":"experimental"}]'::jsonb, 'B', null, 'The contrast is between something set aside in favour of newer technology and its subsequent return, so the word must mean out of date. ''Hazardous'' is contradicted by the passage''s account of its safer failure mode.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('86000865-d7a2-5325-a4a4-61bb9fad6d86', '9a97ea22-391b-5b39-a318-f200a343454c', 3, 'craft_structure', 'words_in_context', 'hard', 'mc', 'The distinction the essay draws is _______ but consequential: it separates readers who abandon a book from readers who merely pause, and the two groups turn out to respond to entirely different kinds of recommendation.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"arbitrary"},{"key":"B","text":"familiar"},{"key":"C","text":"subtle"},{"key":"D","text":"conclusive"}]'::jsonb, 'C', null, 'The word is set against ''consequential'', so it must concede that the distinction is fine or easy to miss while its effects are large. ''Arbitrary'' would imply the distinction is groundless, which the evidence about different responses contradicts.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a45fa615-b951-5e6a-af5b-5ced280319f6', '9a97ea22-391b-5b39-a318-f200a343454c', 4, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Reviewers treated the study''s central claim as settled, but the author herself was more _______, describing the result as one reading of a noisy data set and calling explicitly for replication.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"indifferent"},{"key":"B","text":"emphatic"},{"key":"C","text":"evasive"},{"key":"D","text":"circumspect"}]'::jsonb, 'D', null, 'The author qualifies her own result and asks for replication, which is cautious rather than confident. ''Evasive'' wrongly suggests she was avoiding the question, when in fact she stated her uncertainty openly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('22097cbc-f14b-5570-a355-fd9d6a3556bd', '9a97ea22-391b-5b39-a318-f200a343454c', 5, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'Standard accounts of the printing revolution emphasise the speed of reproduction. Speed alone, though, does not explain why print reshaped scholarship: hand-copied manuscripts could be produced quickly enough by a large enough scriptorium. What print added was that every copy was identical, so a scholar in one city could cite a page number and be understood in another.', 'What is the main purpose of the text?', '[{"key":"A","text":"To replace a common explanation of print''s impact with a more precise one"},{"key":"B","text":"To argue that manuscripts were produced faster than is generally believed"},{"key":"C","text":"To describe the working conditions inside a medieval scriptorium"},{"key":"D","text":"To trace the spread of page numbering across European universities"}]'::jsonb, 'A', null, 'The passage names the standard explanation, shows it insufficient, and substitutes uniformity of copies. Choice B picks up a supporting point — scriptoria could be fast — and mistakes it for the purpose.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5fa36461-5309-52b6-a1ed-d2d313f024bb', '9a97ea22-391b-5b39-a318-f200a343454c', 6, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'The following is adapted from a novel. The letter had lain in the drawer for eleven years. Meskerem knew its contents by heart and had never once reread it. She had kept it the way one keeps a key to a house long since sold.', 'What is the main function of the simile in the last sentence?', '[{"key":"A","text":"It suggests that the character intends to return to a former home."},{"key":"B","text":"It conveys that the letter is retained out of habit rather than usefulness."},{"key":"C","text":"It implies that the character has forgotten why she kept the letter."},{"key":"D","text":"It indicates that the letter contains legal instructions about property."}]'::jsonb, 'B', null, 'A key to a sold house cannot open anything, so keeping it is sentiment or habit rather than practical use — which matches a letter she never rereads. Choice C is ruled out by her knowing the contents by heart.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d0f3c219-c00a-5793-a56f-29bc7bdb822c', '9a97ea22-391b-5b39-a318-f200a343454c', 7, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: An economist argues that cash transfers are the most effective form of aid, since recipients understand their own needs better than distant agencies do.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('193da671-445d-5974-a594-d0a7f3acce28', '9a97ea22-391b-5b39-a318-f200a343454c', 8, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: A literary scholar contends that an author''s letters should not be used to interpret their fiction, since a writer''s stated intentions are just one more piece of writing, no more authoritative than the novel itself.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('bc272949-8a31-5f49-a221-7b02792f0c91', '9a97ea22-391b-5b39-a318-f200a343454c', 9, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'Coral reefs are often described as the rainforests of the sea, but the comparison misleads in one respect. Rainforest soils are rich; reef waters are famously poor in nutrients. A reef''s productivity comes not from abundance but from recycling — nutrients pass between coral, algae, and fish so efficiently that very little escapes into open water.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"A reef''s productivity depends on efficient recycling rather than on rich surroundings."},{"key":"B","text":"Coral reefs and rainforests support similar numbers of species."},{"key":"C","text":"Nutrient-poor waters cannot support large populations of fish."},{"key":"D","text":"The comparison between reefs and rainforests should be abandoned entirely."}]'::jsonb, 'A', null, 'The passage corrects the analogy on one specific point and explains that productivity comes from recycling in nutrient-poor water. Choice D goes further than the text, which limits its objection to ''one respect''.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('56659eb3-3a91-5b38-aa64-7c69ce5c7c63', '9a97ea22-391b-5b39-a318-f200a343454c', 10, 'information_ideas', 'central_ideas_details', 'hard', 'mc', 'It is often said that photography made portrait painting obsolete. The commissions tell a different story. Portrait painting did contract sharply in the 1860s, but it recovered within two decades, having changed its purpose: sitters who wanted a likeness now went to a photographer, and those who went to a painter wanted something a camera could not offer — an interpretation.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Photography permanently ended the market for painted portraits."},{"key":"B","text":"Painted portraiture survived photography by taking on a different function."},{"key":"C","text":"Portrait painters in the 1860s adopted photographic techniques."},{"key":"D","text":"Photographs were considered more accurate than paintings by most sitters."}]'::jsonb, 'B', null, 'The passage concedes the contraction, reports the recovery, and attributes it to a changed purpose — interpretation rather than likeness. Choice A states the very claim the evidence is offered to refute.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('588d7549-da46-5e98-a068-d5a38b0119ba', '9a97ea22-391b-5b39-a318-f200a343454c', 11, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'A researcher argues that the abandonment of the settlement was gradual and planned rather than sudden, contrary to the long-standing assumption that it was evacuated during a single crisis.', 'Which finding, if true, would most directly support the researcher''s argument?', '[{"key":"A","text":"A layer of ash covers the uppermost floor surfaces across the site."},{"key":"B","text":"The settlement''s population had grown steadily in the preceding century."},{"key":"C","text":"Heavy grinding stones were removed from houses, while broken pottery was left in place."},{"key":"D","text":"Several neighbouring settlements were abandoned during the same period."}]'::jsonb, 'C', null, 'Taking valuable, heavy items while leaving worthless ones behind is the signature of an orderly departure with time to choose. Choice A points toward the sudden catastrophe the researcher is arguing against.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('64ece03f-1c0f-539d-a83c-6d279945d7d7', '9a97ea22-391b-5b39-a318-f200a343454c', 12, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'A psychologist proposes that the benefit of handwritten notes over typed ones comes from the slowness of handwriting, which forces students to summarise rather than transcribe.', 'Which finding, if true, would most directly weaken the psychologist''s proposal?', '[{"key":"A","text":"Students who handwrite notes recall more of a lecture a week later than students who type."},{"key":"B","text":"Handwriting speed varies considerably between individual students."},{"key":"C","text":"Students generally prefer typing to handwriting for long lectures."},{"key":"D","text":"Students told to type only summaries recall as much as students who handwrite freely."}]'::jsonb, 'D', null, 'If typing while summarising matches handwriting, the benefit tracks the act of summarising rather than the slowness of the hand — which is the mechanism the proposal specifies. Choice A supports the phenomenon without testing the proposed cause.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('628d52eb-d6de-5faf-a67c-5692cb312a7d', '9a97ea22-391b-5b39-a318-f200a343454c', 13, 'information_ideas', 'evidence_quantitative', 'hard', 'mc', 'A city compared four bus routes after adding dedicated lanes. On Route 1, average journey time fell from 42 to 31 minutes and ridership rose 18%. On Route 2, time fell from 38 to 35 minutes and ridership rose 3%. On Route 3, time fell from 55 to 39 minutes and ridership rose 26%. On Route 4, time fell from 29 to 27 minutes and ridership was unchanged.', 'Which statement is best supported by the data?', '[{"key":"A","text":"Routes with larger reductions in journey time showed larger increases in ridership."},{"key":"B","text":"Every route showed an increase in ridership after the lanes were added."},{"key":"C","text":"Route 3 had the shortest journey time after the lanes were added."},{"key":"D","text":"Ridership rose by the same proportion as journey time fell on each route."}]'::jsonb, 'A', null, 'The time savings were 11, 3, 16 and 2 minutes, and the ridership gains were 18%, 3%, 26% and 0% — larger savings accompany larger gains throughout. Choice B fails on Route 4, and choice C is wrong because Route 4 ends at 27 minutes.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ce526ac9-3013-5b85-abb4-46a625d134b1', '9a97ea22-391b-5b39-a318-f200a343454c', 14, 'information_ideas', 'inferences', 'hard', 'mc', 'Restorers cleaning a sixteenth-century altarpiece found that the varnish they were removing had itself been applied over an earlier cleaning, one that had already stripped some of the original glazes. The damage they were uncovering, in other words, was not the work of time but of a previous restoration. Any decision about how far to clean must therefore _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"be postponed until the identity of the earlier restorer is established."},{"key":"B","text":"reckon with the possibility that removing later layers will not reveal an intact original."},{"key":"C","text":"involve replacing the missing glazes with modern equivalents."},{"key":"D","text":"assume that the surface beneath the varnish is in its sixteenth-century state."}]'::jsonb, 'B', null, 'If an earlier cleaning already removed original glazes, then stripping the varnish cannot restore what is no longer there. Choice D asserts exactly the assumption the passage has just disproved.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2a6d1f7e-476b-573e-ad46-7d2d077c9031', '9a97ea22-391b-5b39-a318-f200a343454c', 15, 'information_ideas', 'inferences', 'hard', 'mc', 'Desert ants navigate by counting steps, and a series of experiments confirmed it neatly: ants given stilts overshot the nest, while ants whose legs were shortened stopped short. Both groups, however, corrected on the return journey, arriving accurately the second time. This indicates that the step counter _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"operates independently of any information about the terrain."},{"key":"B","text":"is used only by ants that have never left the nest before."},{"key":"C","text":"is recalibrated against the distance actually travelled on a completed trip."},{"key":"D","text":"becomes less accurate each time a journey is repeated."}]'::jsonb, 'C', null, 'The ants erred once and then corrected with the same altered legs, so something must have updated the internal measure using the trip just completed. Choice D reverses the result, which was improvement rather than decay.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('af1fe7f0-30b9-5ed1-a3c0-ae88695cfc8a', '9a97ea22-391b-5b39-a318-f200a343454c', 16, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The seed bank stores samples at −20°C _______ at that temperature, most varieties remain viable for decades.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":" "},{"key":"C","text":", and it is "},{"key":"D","text":"; "}]'::jsonb, 'D', null, 'Both sides are complete sentences, so a semicolon is required; a comma alone would splice them. Choice C adds a conjunction but produces a redundant and ungrammatical second clause.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e83d3357-38fd-5ec6-a382-fb6f4593a574', '9a97ea22-391b-5b39-a318-f200a343454c', 17, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'Neither the surveyor''s field notes nor the later published map _______ any mention of the smaller of the two rivers.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"makes"},{"key":"B","text":"make"},{"key":"C","text":"have made"},{"key":"D","text":"are making"}]'::jsonb, 'A', null, 'With ''neither … nor'', the verb agrees with the nearer subject, which is the singular ''map''. The plural ''notes'' earlier in the sentence is what makes the plural forms tempting.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('05dc7c7e-da14-561e-ad7d-9f05930964a1', '9a97ea22-391b-5b39-a318-f200a343454c', 18, 'standard_conventions', 'boundaries', 'hard', 'mc', 'Wangari Maathai _______ was awarded the Nobel Peace Prize in 2004.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":" who founded the Green Belt Movement in 1977,"},{"key":"B","text":", who founded the Green Belt Movement in 1977,"},{"key":"C","text":", who founded the Green Belt Movement in 1977"},{"key":"D","text":" who founded the Green Belt Movement in 1977"}]'::jsonb, 'B', null, 'The relative clause adds non-essential information about a person already identified by name, so it takes commas on both sides. A single comma leaves the interrupter open and separates the subject from ''was awarded''.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e67b132b-e08f-53fa-acb5-472b6c4a8e79', '9a97ea22-391b-5b39-a318-f200a343454c', 19, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The expedition''s supplies were chosen for weight rather than variety _______ dried meat, hard biscuit, and tea made up nearly the entire list.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"; and "},{"key":"B","text":", "},{"key":"C","text":": "},{"key":"D","text":" which "}]'::jsonb, 'C', null, 'The second half illustrates the general statement that precedes it, and a colon after a complete sentence is the conventional way to introduce that illustration. Choice A is wrong because a semicolon is not combined with a coordinating conjunction.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e495adbb-f650-5cf8-a7fa-be54430fab19', '9a97ea22-391b-5b39-a318-f200a343454c', 20, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'The committee released its findings in March _______ by then the contract had already been signed and the site cleared.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":" "},{"key":"C","text":" and, "},{"key":"D","text":"; "}]'::jsonb, 'D', null, 'Two independent clauses joined without a conjunction require a semicolon. ''By then'' is an adverbial phrase, not a conjunction, so it cannot hold the two clauses together after a comma.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e0f10524-60ea-550e-a535-7ef30f6b7865', '9a97ea22-391b-5b39-a318-f200a343454c', 21, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'Written in a shorthand that no living scholar could read _______ for more than a century after its discovery.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"the diary remained untranslated"},{"key":"B","text":"translators were unable to work on the diary"},{"key":"C","text":"there was no translation of the diary"},{"key":"D","text":"it proved impossible to translate the diary"}]'::jsonb, 'A', null, 'The opening modifier describes what was written in shorthand, so the diary must directly follow it as the subject. Choices B, C and D place translators, ''there'' and ''it'' in that position, none of which was written in shorthand.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c41852d2-9acb-50d1-ab2f-51c53b88c0b5', '9a97ea22-391b-5b39-a318-f200a343454c', 22, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'Researchers had assumed the crater was volcanic until shocked quartz _______ at the rim in 1991, confirming an impact origin.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"has been identified"},{"key":"B","text":"was identified"},{"key":"C","text":"is identified"},{"key":"D","text":"will be identified"}]'::jsonb, 'B', null, 'The sentence is anchored to a completed past moment, 1991, so the simple past passive is required. The present perfect in choice A cannot take a specific past time marker.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1d2cb01d-3ff2-5ecf-a8b0-f8ad71646c11', '9a97ea22-391b-5b39-a318-f200a343454c', 23, 'expression_ideas', 'transitions', 'hard', 'mc', 'The alloy is far stronger than aluminium and only slightly heavier, which makes it attractive for aircraft frames. _______ it corrodes rapidly in salt air, which has limited its use in maritime aviation.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Consequently,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"However,"},{"key":"D","text":"For instance,"}]'::jsonb, 'C', null, 'The first sentence gives an advantage and the second a drawback that restricts use, so the relationship is contrast. ''Moreover'' would signal another point in the same direction, which corrosion is not.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('62538032-0553-5b96-a319-c468482cfcca', '9a97ea22-391b-5b39-a318-f200a343454c', 24, 'expression_ideas', 'transitions', 'hard', 'mc', 'Early estimates of the manuscript''s age relied on the style of its script, a method that can be out by fifty years in either direction. Radiocarbon dating narrowed the range to a single decade. _______ the palaeographic estimate was not discarded: it remains the only way to date the many fragments too small to sample.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"As a result,"},{"key":"B","text":"Likewise,"},{"key":"C","text":"In short,"},{"key":"D","text":"Even so,"}]'::jsonb, 'D', null, 'Radiocarbon dating is more precise, so one would expect the older method to be abandoned; the sentence concedes that it was not. ''As a result'' would make retention follow from the new precision, which reverses the logic.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('63e4af6f-474f-5616-a7c9-c7ee1942d167', '9a97ea22-391b-5b39-a318-f200a343454c', 25, 'expression_ideas', 'transitions', 'hard', 'mc', 'The survey found that most respondents could not name their local representative. _______ the same respondents correctly identified the representative''s party and two of their recent votes.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Therefore,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"Accordingly,"}]'::jsonb, 'A', null, 'Not knowing a name while knowing the party and voting record is unexpected, so the second fact stands against the first. ''Similarly'' would require the two findings to point the same way, but they cut in opposite directions.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('563fa2dd-f0c9-5d7b-a7a2-07604261f3e1', '9a97ea22-391b-5b39-a318-f200a343454c', 26, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching, a student has taken these notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0941a3b5-8bfa-5312-a4e5-a0474a3c553f', '9a97ea22-391b-5b39-a318-f200a343454c', 27, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching, a student has taken these notes:
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('390c3cd8-83ba-5e33-a1bc-19093a41e597', 'af388eaa-9708-5e69-af52-371229c85588', 3, 'Math — Module 1', 'math', 2100) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('83ac862c-7c8c-5652-a0e8-41ff43b089bb', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 1, 'algebra', 'linear_eq_one_var', 'easy', 'mc', null, 'If 7(x − 3) = 2x + 4, what is the value of x?', '[{"key":"A","text":"5"},{"key":"B","text":"3"},{"key":"C","text":"7"},{"key":"D","text":"25"}]'::jsonb, 'A', null, 'Distributing gives 7x − 21 = 2x + 4, so 5x = 25 and x = 5. Choice D is the value of 5x, which is the most common place to stop early.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4e646a4c-58e6-5f93-a552-4d9a02b3b832', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 2, 'advanced_math', 'equivalent_expressions', 'easy', 'mc', null, 'Which expression is equivalent to (2x³)(5x⁴)?', '[{"key":"A","text":"10x¹²"},{"key":"B","text":"10x⁷"},{"key":"C","text":"7x⁷"},{"key":"D","text":"7x¹²"}]'::jsonb, 'B', null, 'Multiply the coefficients and add the exponents: 2 × 5 = 10 and x³ · x⁴ = x⁷. Choice A multiplies the exponents instead of adding them, and choices C and D add the coefficients.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d9b39946-7a90-5911-a92a-7ee06631517a', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 3, 'algebra', 'linear_functions', 'medium', 'spr', null, 'A line passes through the points (2, 7) and (6, 19). What is the y-coordinate of the point where this line crosses the y-axis?', null, '1', '["1.0"]'::jsonb, 'The slope is (19 − 7)/(6 − 2) = 12/4 = 3. Substituting (2, 7) into y = 3x + b gives 7 = 6 + b, so b = 1. Answering 7 mistakes the given point for the intercept.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d55454a1-5662-5323-ac30-083170887e2a', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 4, 'algebra', 'linear_eq_two_var', 'medium', 'mc', null, 'Line ℓ has equation 2x + 5y = 20. Line m is perpendicular to ℓ and passes through the point (4, 1). What is the y-intercept of line m?', '[{"key":"A","text":"−1"},{"key":"B","text":"1"},{"key":"C","text":"9"},{"key":"D","text":"−9"}]'::jsonb, 'D', null, 'Line ℓ has slope −2/5, so a perpendicular line has slope 5/2. Using y − 1 = (5/2)(x − 4) gives y = (5/2)x − 9, so the y-intercept is −9. Choice C drops the sign produced by −(5/2)(4) + 1.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('029db67a-11b2-569d-a51e-6d3091e70c1e', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 5, 'algebra', 'systems_two_linear', 'medium', 'mc', null, 'If 3x + 2y = 16 and 5x − 2y = 8, what is the value of x + y?', '[{"key":"A","text":"6.5"},{"key":"B","text":"3"},{"key":"C","text":"3.5"},{"key":"D","text":"10"}]'::jsonb, 'A', null, 'Adding the equations eliminates y: 8x = 24, so x = 3. Then 9 + 2y = 16 gives y = 3.5, and x + y = 6.5. Choices B and C are the individual values — the question asks for their sum, which is exactly the trap.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3978141b-3acb-59ee-accc-71f0c09c70c6', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 6, 'algebra', 'linear_inequalities', 'medium', 'mc', null, 'A caterer charges a fixed setup fee of 120 birr plus 45 birr for each guest. If the total cost must not exceed 2,900 birr, what is the greatest number of guests that can be served?', '[{"key":"A","text":"60"},{"key":"B","text":"61"},{"key":"C","text":"62"},{"key":"D","text":"66"}]'::jsonb, 'B', null, 'The amount available for guests is 2,900 − 120 = 2,780 birr, and 2,780 ÷ 45 ≈ 61.8, so only 61 whole guests fit. Choice C rounds up, which would push the total over the limit.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7ad03170-755b-5858-a24e-919745a39de0', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 7, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The function f is defined by f(x) = x² − 6x + 5. What is the minimum value of f(x)?', '[{"key":"A","text":"−3"},{"key":"B","text":"3"},{"key":"C","text":"−4"},{"key":"D","text":"5"}]'::jsonb, 'C', null, 'The vertex lies at x = −b/(2a) = 6/2 = 3, and f(3) = 9 − 18 + 5 = −4. Choice B is the x-coordinate of the vertex rather than the minimum value, which is the y-coordinate.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('73420919-5d92-5efa-a2be-f43365c38248', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 8, 'advanced_math', 'nonlinear_eq_systems', 'medium', 'spr', null, 'What is the positive solution to the equation x² = 4x + 21?', null, '7', '["7.0"]'::jsonb, 'Rearranging gives x² − 4x − 21 = 0, which factors as (x − 7)(x + 3) = 0, so x = 7 or x = −3. The question asks only for the positive solution, so 7 is the answer.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('254bd33d-f874-56c0-a45a-e7683b8737b4', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 9, 'advanced_math', 'equivalent_expressions', 'medium', 'mc', null, 'For x ≠ 3 and x ≠ −3, which expression is equivalent to (x + 3)/(x² − 9)?', '[{"key":"A","text":"1/(x − 3)"},{"key":"B","text":"1/(x + 3)"},{"key":"C","text":"x − 3"},{"key":"D","text":"1/9"}]'::jsonb, 'A', null, 'The denominator factors as (x + 3)(x − 3), so the (x + 3) cancels and leaves 1/(x − 3). Choice B cancels the wrong factor, which is the natural slip when the numerator is matched to the first factor written.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fbb47a88-3166-52a5-abb3-6336f6609f5e', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 10, 'psda', 'percentages', 'medium', 'mc', null, 'A jacket is marked down by 30%. During a later sale, that reduced price is marked down by a further 20%. The final price is what percent of the original price?', '[{"key":"A","text":"44%"},{"key":"B","text":"56%"},{"key":"C","text":"50%"},{"key":"D","text":"60%"}]'::jsonb, 'B', null, 'Successive discounts multiply: 0.70 × 0.80 = 0.56, so the final price is 56% of the original. Choice C comes from adding the discounts to get 50% off, which double-counts the amount already removed.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a37b2beb-147a-565e-a5b5-2cd5e47ffeaf', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 11, 'psda', 'one_var_data', 'medium', 'mc', null, 'Data set B is created by adding 12 to each of the values in data set A. Which of the following correctly compares the medians and the ranges of the two data sets?', '[{"key":"A","text":"The median of B equals the median of A, and the range of B equals the range of A."},{"key":"B","text":"The median of B is greater than the median of A, and the range of B is greater than the range of A."},{"key":"C","text":"The median of B is greater than the median of A, and the range of B equals the range of A."},{"key":"D","text":"The median of B equals the median of A, and the range of B is greater than the range of A."}]'::jsonb, 'C', null, 'Adding a constant slides every value up, so the median increases by 12. The range is a difference between two values, and both shift equally, so the difference is unchanged. Choice B wrongly assumes anything that shifts the data must also spread it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c94c3b9c-127f-5781-a0e6-46c4b5e9c054', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 12, 'geometry_trig', 'right_triangles_trig', 'medium', 'mc', null, 'In right triangle ABC, angle C is a right angle and sin(A) = 5/13. What is the value of cos(A)?', '[{"key":"A","text":"5/12"},{"key":"B","text":"13/12"},{"key":"C","text":"5/13"},{"key":"D","text":"12/13"}]'::jsonb, 'D', null, 'If sin(A) = opposite/hypotenuse = 5/13, the third side is √(13² − 5²) = 12, so cos(A) = 12/13. Choice A is tan(A), which uses the two legs rather than a leg and the hypotenuse.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('35ef1be8-17de-569a-ad2b-4bca7d05904f', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 13, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'kx + 3y = 12 and 4x + 6y = 30. For what value of k does this system of equations have no solution?', '[{"key":"A","text":"2"},{"key":"B","text":"1"},{"key":"C","text":"4"},{"key":"D","text":"8"}]'::jsonb, 'A', null, 'A system has no solution when the lines are parallel but distinct, so the coefficients must be proportional while the constants are not: k/4 = 3/6 gives k = 2. Checking, 12/30 ≠ 1/2, so the lines really are distinct rather than identical.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('affd55f1-75cb-586c-a3e3-445a5c12990a', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 14, 'algebra', 'linear_eq_two_var', 'hard', 'mc', null, 'The graph of 3x + ky = 12 in the xy-plane passes through the points (2, 3) and (6, −3). What is the value of k?', '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"6"}]'::jsonb, 'B', null, 'Substituting (2, 3) gives 6 + 3k = 12, so k = 2. Verifying with the second point: 3(6) + 2(−3) = 18 − 6 = 12, which confirms it. Using only one point without checking is what makes the other values look plausible.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('be64efe4-fa7c-5896-a24c-5c4dd7eedc2d', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 15, 'algebra', 'linear_functions', 'hard', 'spr', null, 'The function f is linear, with f(3) = 11 and f(7) = 3. For what value of x does f(x) = 0?', null, '8.5', '["17/2","8.50"]'::jsonb, 'The slope is (3 − 11)/(7 − 3) = −2, so f(x) = 11 − 2(x − 3) = 17 − 2x. Setting 17 − 2x = 0 gives x = 8.5. Answering 17 solves for the y-intercept instead of the x-intercept.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('daebd477-346f-54ce-a093-70a51c228388', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 16, 'advanced_math', 'nonlinear_functions', 'hard', 'mc', null, 'The function g is defined by g(x) = 2(x − 4)² − 18. The graph of y = g(x) crosses the x-axis at x = a and x = b, where a < b. What is the value of b − a?', '[{"key":"A","text":"3"},{"key":"B","text":"9"},{"key":"C","text":"18"},{"key":"D","text":"6"}]'::jsonb, 'D', null, 'Setting 2(x − 4)² − 18 = 0 gives (x − 4)² = 9, so x − 4 = ±3 and the zeros are 1 and 7. Their difference is 6. Choice A gives only the distance from the vertex to one zero.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c8c994dc-427a-571c-a937-4df9e62fac8a', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 17, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'mc', null, 'The system of equations y = x² − 2x + 5 and y = k has exactly one solution. What is the value of k?', '[{"key":"A","text":"4"},{"key":"B","text":"0"},{"key":"C","text":"5"},{"key":"D","text":"6"}]'::jsonb, 'A', null, 'A horizontal line meets a parabola exactly once only at the vertex. The vertex is at x = 1, where y = 1 − 2 + 5 = 4, so k = 4. Choice C is the y-intercept, which the line would cross twice.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('527ba017-d44b-57e3-a328-777c3540695f', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 18, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'spr', null, 'What is the solution to the equation √(2x + 7) = x − 4?', null, '9', '["9.0"]'::jsonb, 'Squaring gives 2x + 7 = x² − 8x + 16, so x² − 10x + 9 = 0 and (x − 1)(x − 9) = 0, giving x = 1 or x = 9. Checking both matters: x = 1 gives √9 = 3 but 1 − 4 = −3, so it is extraneous; only x = 9 works, since √25 = 5 = 9 − 4.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7a5e0f27-efcd-565c-a882-ddd9c5a11041', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 19, 'advanced_math', 'nonlinear_functions', 'hard', 'mc', null, 'The value of a machine, in dollars, is modeled by V(t) = 5,000(0.36)^(t/24), where t is the number of months since it was purchased. By what percent does the value of the machine decrease each year?', '[{"key":"A","text":"18%"},{"key":"B","text":"36%"},{"key":"C","text":"40%"},{"key":"D","text":"60%"}]'::jsonb, 'C', null, 'One year is 12 months, so the yearly factor is 0.36^(12/24) = 0.36^(1/2) = 0.6, meaning 60% of the value remains and 40% is lost. Choice D reports the fraction remaining rather than the decrease, and choice B uses the two-year factor without converting.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d7e83264-577c-5950-af99-95cf3abe9d7f', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 20, 'psda', 'sample_stats_moe', 'hard', 'mc', null, 'A random sample of 200 residents of a city was surveyed, and the mean commute time was found to be 34 minutes, with an associated margin of error of 2.5 minutes at a 95% confidence level. Which statement is the most appropriate conclusion?', '[{"key":"A","text":"Every resident of the city has a commute between 31.5 and 36.5 minutes."},{"key":"B","text":"The mean commute time of the 200 residents surveyed is between 31.5 and 36.5 minutes."},{"key":"C","text":"It is plausible that the mean commute time for all people in the country is between 31.5 and 36.5 minutes."},{"key":"D","text":"It is plausible that the mean commute time for all residents of the city is between 31.5 and 36.5 minutes."}]'::jsonb, 'D', null, 'A margin of error describes a plausible interval for the population mean, and the population here is the residents of that city. Choice A applies an interval about an average to every individual, and choice B describes the sample, whose mean is known exactly to be 34.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4cc98a97-b2d5-5e51-ad86-13d6f403489e', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 21, 'geometry_trig', 'circles', 'hard', 'spr', null, 'The equation x² + y² − 6x + 8y = 0 represents a circle in the xy-plane. What is the radius of the circle?', null, '5', '["5.0"]'::jsonb, 'Completing the square gives (x − 3)² + (y + 4)² = 9 + 16 = 25, so the radius is √25 = 5. Answering 25 reports r² rather than r, which is the usual slip once the squares are completed.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('29a82b98-162f-5a05-acf0-9c1fd4940e10', '390c3cd8-83ba-5e33-a1bc-19093a41e597', 22, 'geometry_trig', 'area_volume', 'hard', 'mc', null, 'A right circular cylinder has a volume of 96π cubic centimeters. A second cylinder has twice the radius and half the height of the first. What is the volume, in cubic centimeters, of the second cylinder?', '[{"key":"A","text":"48π"},{"key":"B","text":"192π"},{"key":"C","text":"96π"},{"key":"D","text":"384π"}]'::jsonb, 'B', null, 'Volume is πr²h, so doubling the radius multiplies the volume by 4 while halving the height divides it by 2, giving a net factor of 2: 2 × 96π = 192π. Choice C assumes the two changes cancel, which ignores that the radius is squared.') on conflict (id) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 'af388eaa-9708-5e69-af52-371229c85588', 4, 'Math — Module 2', 'math', 2100) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0e353ea6-0bf9-52a6-af49-f1c2d70c8299', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 1, 'algebra', 'linear_eq_one_var', 'medium', 'mc', null, 'If 2(x + 5) − 3(x − 1) = 4, what is the value of x?', '[{"key":"A","text":"9"},{"key":"B","text":"−9"},{"key":"C","text":"3"},{"key":"D","text":"13"}]'::jsonb, 'A', null, 'Distributing gives 2x + 10 − 3x + 3 = 4, so −x + 13 = 4 and x = 9. Choice B comes from mishandling the sign when dividing by −1 at the final step.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ec6abebb-3856-5338-a441-c395680d6240', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 2, 'algebra', 'linear_functions', 'medium', 'mc', null, 'What is the slope of the line that passes through the points (−2, 5) and (4, −7)?', '[{"key":"A","text":"−1/2"},{"key":"B","text":"−2"},{"key":"C","text":"1/2"},{"key":"D","text":"2"}]'::jsonb, 'B', null, 'The slope is (−7 − 5)/(4 − (−2)) = −12/6 = −2. Choice A inverts the rise and the run, which is the most common error when the numbers do not divide evenly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('77e7bee4-6979-555c-ac7e-c6efe55a9b6b', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 3, 'algebra', 'linear_eq_one_var', 'medium', 'mc', null, 'If (2x + 1)/3 + (x − 4)/2 = 3, what is the value of x?', '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"7"}]'::jsonb, 'C', null, 'Multiplying through by 6 clears the fractions: 2(2x + 1) + 3(x − 4) = 18, so 4x + 2 + 3x − 12 = 18 and 7x = 28, giving x = 4. Multiplying only one term by 6 is what produces the other values.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('19f23468-6b98-54c4-a777-86415dc660ac', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 4, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The function f is defined by f(x) = 3x² − 12x + 7. What is the x-coordinate of the vertex of the graph of y = f(x)?', '[{"key":"A","text":"−2"},{"key":"B","text":"4"},{"key":"C","text":"7"},{"key":"D","text":"2"}]'::jsonb, 'D', null, 'The vertex is at x = −b/(2a) = 12/6 = 2. Choice A drops the negative sign in the formula, and choice B uses b/a without halving it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('80ef5888-8fe7-5c30-a05b-e761ca277733', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 5, 'advanced_math', 'equivalent_expressions', 'medium', 'mc', null, 'For x > 0, which expression is equivalent to x^(1/2) · x^(3/4)?', '[{"key":"A","text":"x^(5/4)"},{"key":"B","text":"x^(3/8)"},{"key":"C","text":"x^(2/3)"},{"key":"D","text":"x^(1/4)"}]'::jsonb, 'A', null, 'Multiplying powers of the same base adds the exponents: 1/2 + 3/4 = 5/4. Choice B multiplies the exponents instead, and choice D subtracts them.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b07cfc8c-23ae-5af3-af2b-f90cd9cbd637', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 6, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'The system of equations 6x − 4y = 10 and −9x + 6y = c has infinitely many solutions. What is the value of c?', '[{"key":"A","text":"−10"},{"key":"B","text":"−15"},{"key":"C","text":"10"},{"key":"D","text":"15"}]'::jsonb, 'B', null, 'Infinitely many solutions means the two equations describe the same line. Multiplying the first equation by −3/2 gives −9x + 6y = −15, so c = −15. Choice D has the right magnitude but ignores that the multiplier is negative.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cef39e95-7515-5608-a5d1-90c642b8ad66', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 7, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'How many solutions (x, y) does the system consisting of the three equations 3x + 2y = 7, 6x + 4y = 14, and x − y = 4 have?', '[{"key":"A","text":"Zero"},{"key":"B","text":"Exactly two"},{"key":"C","text":"Exactly one"},{"key":"D","text":"Infinitely many"}]'::jsonb, 'C', null, 'The second equation is exactly twice the first, so those two describe the same line rather than adding a new constraint. That line and x − y = 4 have different slopes, so they meet at exactly one point. Choice D treats the duplicated equation as if it made the whole system dependent.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('695e9693-b1c0-5454-a898-d11aca65b207', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 8, 'algebra', 'systems_two_linear', 'hard', 'spr', null, 'If 5x − 3y = 21 and 2x + y = 4, what is the value of x + y?', null, '1', '["1.0"]'::jsonb, 'From the second equation, y = 4 − 2x. Substituting gives 5x − 3(4 − 2x) = 21, so 11x = 33 and x = 3, which makes y = −2. Therefore x + y = 1. Stopping at x = 3 is the trap the question is built around.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7003e7e0-47eb-572d-ac12-bc55831ad6fc', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 9, 'algebra', 'linear_functions', 'hard', 'mc', null, 'A tank holds 500 liters of water. Water drains out at a constant 12 liters per minute while simultaneously being added at a constant 5 liters per minute. After how many minutes does the tank contain 220 liters?', '[{"key":"A","text":"40"},{"key":"B","text":"23"},{"key":"C","text":"29"},{"key":"D","text":"70"}]'::jsonb, 'A', null, 'The net rate is 12 − 5 = 7 liters lost per minute, so 500 − 7t = 220 gives 7t = 280 and t = 40. Choice B uses only the draining rate and ignores the water being added.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c8839bfc-7bb0-5402-abff-dfb5b841306d', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 10, 'algebra', 'linear_functions', 'hard', 'mc', null, 'The graph of the line y = mx + b passes through the points (3, −1) and (−1, 7). What is the value of m + b?', '[{"key":"A","text":"−2"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"7"}]'::jsonb, 'B', null, 'The slope is (7 − (−1))/(−1 − 3) = 8/(−4) = −2, and substituting (3, −1) gives −1 = −6 + b, so b = 5. Therefore m + b = 3. Choices A and C are the two components separately.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('eddc0c8e-f1eb-57d0-a117-e05181fa5d54', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 11, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'spr', null, 'In the equation 4x² + bx + 9 = 0, b is a positive constant and the equation has exactly one real solution. What is the value of b?', null, '12', '["12.0"]'::jsonb, 'Exactly one real solution means the discriminant is zero: b² − 4(4)(9) = 0, so b² = 144 and b = ±12. Since b is given as positive, b = 12.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3ecf0ecd-d5f8-5a95-a823-ff4f1510c85c', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 12, 'advanced_math', 'nonlinear_functions', 'hard', 'spr', null, 'If (x − 3) is a factor of the polynomial x³ − 4x² + kx − 6, what is the value of k?', null, '5', '["5.0"]'::jsonb, 'If (x − 3) is a factor then substituting x = 3 must give zero: 27 − 36 + 3k − 6 = 0, so 3k = 15 and k = 5. Substituting x = −3 instead, by misreading the sign of the factor, is the usual error here.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3ca50619-b4d7-58cc-a9fb-0ca72c3f7400', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 13, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'mc', null, 'The graphs of y = x² + 4x + c and y = 2x + 3 intersect at exactly one point in the xy-plane. What is the value of c?', '[{"key":"A","text":"4"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"7"}]'::jsonb, 'A', null, 'Setting the expressions equal gives x² + 2x + (c − 3) = 0, and exactly one intersection means the discriminant is zero: 4 − 4(c − 3) = 0, so c − 3 = 1 and c = 4. Forgetting to move 2x + 3 across before applying the discriminant produces the other choices.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9df2f3bc-f6de-5992-a6e6-7b0ceb17bfb8', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 14, 'advanced_math', 'nonlinear_functions', 'hard', 'mc', null, 'A population is modeled by P(t) = 800(1.21)^(t/2), where t is the number of years since the study began. By what percent does the population increase each year?', '[{"key":"A","text":"10.5%"},{"key":"B","text":"10%"},{"key":"C","text":"21%"},{"key":"D","text":"42%"}]'::jsonb, 'B', null, 'One year corresponds to t = 1, giving a factor of 1.21^(1/2) = 1.1, which is a 10% increase. Choice C reads the two-year growth factor as if it were annual, and choice A halves the percent rather than taking the square root of the factor.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('dd235412-9d42-5ba0-a897-d930744c4a4f', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 15, 'advanced_math', 'equivalent_expressions', 'hard', 'mc', null, 'What is the solution to the equation 1/(x − 2) + 1/(x + 2) = 4/(x² − 4)?', '[{"key":"A","text":"x = −2"},{"key":"B","text":"x = 0"},{"key":"C","text":"There is no solution."},{"key":"D","text":"x = 2"}]'::jsonb, 'C', null, 'Since x² − 4 = (x − 2)(x + 2), multiplying through by that product gives (x + 2) + (x − 2) = 4, so 2x = 4 and x = 2. But x = 2 makes the original denominators zero, so it is extraneous and the equation has no solution. Choice D is what you get by never checking the result against the original equation.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e989abb6-ed73-5be7-afb6-d2b4bfc38307', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 16, 'advanced_math', 'equivalent_expressions', 'hard', 'spr', null, 'If 2^(x + 2) = 40, what is the value of 2^x?', null, '10', '["10.0"]'::jsonb, 'Since 2^(x + 2) = 2^x · 2² = 4 · 2^x, we have 4 · 2^x = 40, so 2^x = 10. No logarithms are needed — separating the exponent is enough, and dividing by 2 instead of 4 is the common slip.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('83cf35c9-c334-5c5b-ac54-dd41e644f8db', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 17, 'psda', 'evaluating_claims', 'hard', 'mc', null, 'A researcher surveyed 500 randomly selected students at one university and found that 62% supported a proposed policy, with an associated margin of error of 4% at a 95% confidence level. Which statement is best supported by these results?', '[{"key":"A","text":"It is plausible that between 58% and 66% of all students at the university support the policy."},{"key":"B","text":"Exactly 62% of all students at the university support the policy."},{"key":"C","text":"It is plausible that between 58% and 66% of all university students in the country support the policy."},{"key":"D","text":"Between 58% and 66% of the 500 students surveyed support the policy."}]'::jsonb, 'A', null, 'The interval applies to the population that was randomly sampled — students at that one university. Choice C generalises beyond the sampled population, choice B treats an estimate as exact, and choice D describes the sample, where the figure is known to be exactly 62%.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b2503565-7bba-5ca0-a2ff-2cb654171492', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 18, 'psda', 'one_var_data', 'hard', 'mc', null, 'The data set 2, 4, 4, 5, 9 is changed by replacing the value 9 with 25. Which of the following statistics changes the least?', '[{"key":"A","text":"The mean"},{"key":"B","text":"The median"},{"key":"C","text":"The range"},{"key":"D","text":"The standard deviation"}]'::jsonb, 'B', null, 'The median is the middle value of the ordered list, which is 4 before and 4 after, so it does not change at all. The mean rises from 4.8 to 8, the range rises from 7 to 23, and the spread grows, so the median is uniquely resistant to a single extreme value.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('354d746e-ab9c-5ed6-a248-c139bcfe08c6', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 19, 'psda', 'probability', 'hard', 'spr', null, 'Of 200 students surveyed, 80 play a sport and 50 of those students also play an instrument. Of the students surveyed, 30 play neither a sport nor an instrument. If a student who does not play a sport is selected at random, what is the probability that the student plays an instrument?', null, '0.75', '["3/4",".75","0.750"]'::jsonb, 'Students who do not play a sport number 200 − 80 = 120, and 30 of those play neither, so 90 of them play an instrument. The probability is 90/120 = 0.75. Dividing by 200 instead of 120 ignores that the question restricts attention to non-athletes.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2b064ddb-76ed-5170-a5d1-c656cbb67816', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 20, 'geometry_trig', 'right_triangles_trig', 'hard', 'mc', null, 'In right triangle PQR, angle Q is a right angle and sin(P) = 20/29. What is the value of cos(R)?', '[{"key":"A","text":"21/29"},{"key":"B","text":"29/20"},{"key":"C","text":"21/20"},{"key":"D","text":"20/29"}]'::jsonb, 'D', null, 'Angles P and R are complementary because angle Q is the right angle, and the cosine of an angle equals the sine of its complement, so cos(R) = sin(P) = 20/29. Choice A is cos(P), found by computing the third side and answering for the wrong angle.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a376f42b-c72a-5295-a37d-c3e17023493e', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 21, 'geometry_trig', 'circles', 'hard', 'spr', null, 'The equation x² + y² + 10x − 4y = 20 represents a circle in the xy-plane. What is the radius of the circle?', null, '7', '["7.0"]'::jsonb, 'Completing the square gives (x + 5)² + (y − 2)² = 20 + 25 + 4 = 49, so the radius is 7. The constants added to complete each square must also be added to the right-hand side, which is the step most often missed.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('97e97ad9-01de-5035-a2b9-7cdbf9049d40', 'fc6115f2-5acb-5d65-ad2b-d566a77dbb66', 22, 'geometry_trig', 'lines_angles_triangles', 'hard', 'mc', null, 'Two similar triangles have perimeters of 12 centimeters and 30 centimeters. If the area of the smaller triangle is 20 square centimeters, what is the area of the larger triangle, in square centimeters?', '[{"key":"A","text":"50"},{"key":"B","text":"125"},{"key":"C","text":"80"},{"key":"D","text":"200"}]'::jsonb, 'B', null, 'The ratio of corresponding lengths is 12:30 = 2:5, and areas scale as the square of that ratio, so the area ratio is 4:25. Therefore the larger area is 20 × 25/4 = 125. Choice A applies the length ratio directly to the area, which is the standard error.') on conflict (id) do nothing;
